package com.gestourant.order; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.time.ZoneId;
@Entity @Table(name="invoices") public class Invoice { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(optional=false) @JoinColumn(name="order_id") private RestaurantOrder order; @Column(name="invoice_number",nullable=false,unique=true) private String invoiceNumber; @Enumerated(EnumType.STRING) @Column(name="payment_method",nullable=false) private PaymentMethod paymentMethod; @Column(nullable=false,precision=12,scale=2) private BigDecimal total; @Column(name="issued_at",nullable=false) private LocalDateTime issuedAt; protected Invoice(){} public Invoice(RestaurantOrder o,PaymentMethod p){order=o;paymentMethod=p;total=o.getTotal();issuedAt=LocalDateTime.now(ZoneId.of("America/Bogota"));invoiceNumber="FAC-"+System.currentTimeMillis()+"-"+o.getId();} public Long getId(){return id;} public RestaurantOrder getOrder(){return order;} public String getInvoiceNumber(){return invoiceNumber;} public PaymentMethod getPaymentMethod(){return paymentMethod;} public BigDecimal getTotal(){return total;} public LocalDateTime getIssuedAt(){return issuedAt;} }
